import axios from 'axios';
import createVaultClient from './client';
import { fetchHashicorpVaultSecrets, vaultWhoami, getVaultServerLdapToken, getVaultCloudSecrets, tokenStorage } from './index';

// The Vault client and agent resolution are mocked so these tests exercise only the auth/LDAP
// orchestration logic, with no real network or TLS work.
jest.mock('./client');
jest.mock('axios');
jest.mock('../../../utils/http-https-agents', () => ({
  getHttpHttpsAgents: jest.fn(async () => ({ httpAgent: undefined, httpsAgent: undefined }))
}));

const mockedCreateVaultClient = createVaultClient as jest.MockedFunction<typeof createVaultClient>;
const mockedAxios = axios as jest.Mocked<typeof axios>;

describe('HashiCorp Vault - LDAP authentication', () => {
  let mockVault: any;

  beforeEach(() => {
    jest.clearAllMocks();
    tokenStorage.vault = {};

    mockVault = {
      endpoint: 'https://vault.example.com',
      namespace: '',
      token: '',
      apiVersion: 'v1',
      tokenLookupSelf: jest.fn(),
      tokenRenewSelf: jest.fn(),
      write: jest.fn(),
      read: jest.fn()
    };

    mockedCreateVaultClient.mockReturnValue(mockVault);
  });

  it('should authenticate with LDAP and store the issued token', async () => {
    mockVault.write.mockResolvedValue({
      auth: { client_token: 'test-token-123', renewable: true, lease_duration: 3600 }
    });

    const result = await getVaultServerLdapToken({
      vault: mockVault,
      options: { username: 'testuser', password: 'testpass' }
    });

    expect(result).toBe('test-token-123');
  });

  it('should throw when auto-renew is false and the stored token is expired', async () => {
    tokenStorage.storeToken(mockVault.endpoint, 'expired-token', { renewable: true });
    mockVault.tokenLookupSelf.mockRejectedValue(new Error('Token expired'));

    const config = {
      type: 'hashicorp-vault-server',
      vaultServerConfig: {
        url: 'https://vault.example.com',
        auth: {
          method: 'ldap',
          ldap: { username: 'testuser', password: 'testpass', autoRenew: false }
        }
      }
    };

    await expect(fetchHashicorpVaultSecrets({ config, paths: ['secret/path1'] })).rejects.toThrow(
      'LDAP token has expired. Auto-renew is disabled. Please re-authenticate.'
    );
  });

  it('should authenticate with LDAP for vaultWhoami', async () => {
    const lookupResponse = { data: { display_name: 'testuser', policies: ['default'] } };
    mockVault.write.mockResolvedValue({
      auth: {
        client_token: 'whoami-token-123',
        renewable: true,
        lease_duration: 3600,
        policies: ['default'],
        metadata: { username: 'testuser' }
      }
    });
    mockVault.tokenLookupSelf.mockResolvedValue(lookupResponse);

    const config = {
      type: 'hashicorp-vault-server',
      vaultServerConfig: {
        url: 'https://vault.example.com',
        auth: {
          method: 'ldap',
          ldap: { username: 'testuser', password: 'testpass', autoRenew: true }
        }
      }
    };

    const result = await vaultWhoami({ type: 'hashicorp-vault-server', config });

    expect(result).toEqual(lookupResponse);
  });
});

describe('HashiCorp Vault Cloud - getVaultCloudSecrets', () => {
  const resolveAgents = jest.fn(async () => ({ httpAgent: undefined, httpsAgent: undefined }));
  const options = {
    secretsEndpoint: 'https://api.cloud.hashicorp.com/secrets/v1',
    organizationId: 'org-1',
    projectId: 'proj-1'
  };

  const page = (secrets: any[], nextPageToken = '') => ({
    data: { secrets, pagination: { next_page_token: nextPageToken } }
  });

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('follows pagination.next_page_token across pages and merges every secret', async () => {
    mockedAxios.get
      .mockResolvedValueOnce(page([{ name: 'A', version: { value: '1' } }], 'token-2'))
      .mockResolvedValueOnce(page([{ name: 'B', version: { value: '2' } }], ''));

    const result = await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my-app', resolveAgents });

    expect(result.data).toEqual({ A: '1', B: '2' });
    expect(mockedAxios.get).toHaveBeenCalledTimes(2);
    // The second request must carry the token returned by the first.
    expect(mockedAxios.get.mock.calls[0][1]).toMatchObject({ params: undefined });
    expect(mockedAxios.get.mock.calls[1][1]).toMatchObject({ params: { 'pagination.next_page_token': 'token-2' } });
  });

  it('makes a single request when there is no next page token', async () => {
    mockedAxios.get.mockResolvedValueOnce(page([{ name: 'ONLY', version: { value: 'v' } }], ''));

    const result = await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my-app', resolveAgents });

    expect(result.data).toEqual({ ONLY: 'v' });
    expect(mockedAxios.get).toHaveBeenCalledTimes(1);
  });

  it('returns an empty result without a request when org/project is missing', async () => {
    const result = await getVaultCloudSecrets({
      options: { secretsEndpoint: options.secretsEndpoint },
      accessToken: 'tok',
      path: 'my-app',
      resolveAgents
    });

    expect(result).toEqual({ path: 'my-app', data: {} });
    expect(mockedAxios.get).not.toHaveBeenCalled();
  });

  it('returns a normalized error when the request fails', async () => {
    mockedAxios.get.mockRejectedValueOnce({ message: 'boom', code: 'ECONNRESET' });

    const result = await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my-app', resolveAgents });

    expect(result.data).toBeUndefined();
    expect(result.error).toMatchObject({ message: 'boom', type: 'network', context: { operation: 'getVaultCloudSecrets', path: 'my-app' } });
  });

  it('returns an error (rather than empty secrets) when a 2xx response has no body', async () => {
    mockedAxios.get.mockResolvedValueOnce({ data: undefined });

    const result = await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my-app', resolveAgents });

    expect(result.data).toBeUndefined();
    expect(result.error).toBeDefined();
  });

  it('stops instead of looping forever when the endpoint returns a non-advancing page token', async () => {
    // The same token is returned on every page; the loop must break once it is seen again.
    mockedAxios.get.mockResolvedValue(page([{ name: 'A', version: { value: '1' } }], 'stuck-token'));

    const result = await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my-app', resolveAgents });

    expect(result.data).toEqual({ A: '1' });
    expect(mockedAxios.get).toHaveBeenCalledTimes(2);
  });

  it('url-encodes the app name derived from the path', async () => {
    mockedAxios.get.mockResolvedValueOnce(page([], ''));

    await getVaultCloudSecrets({ options, accessToken: 'tok', path: 'my app/key', resolveAgents });

    expect(mockedAxios.get.mock.calls[0][0]).toContain('/apps/my%20app/open');
  });
});
